const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  const htmlPath = path.resolve(__dirname, 'poster.html');
  await page.goto('file://' + htmlPath, { waitUntil: 'networkidle' });

  // Wait for fonts
  await page.waitForSelector('body[data-fonts-ready="true"]', { timeout: 15000 });

  // Additional small delay to ensure layout settles
  await page.waitForTimeout(500);

  const poster = await page.$('#poster');
  await poster.screenshot({
    path: path.resolve(__dirname, 'final_poster.png'),
    type: 'png'
  });

  await browser.close();
  console.log('Screenshot saved to final_poster.png');
})();
